import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>Görüntü bölücü bir fotoğrafı birkaç küçük parçaya keser. Parçalar sosyal bir profil için ızgara, kaydırıcı için şeritler ya da büyük bir görüntüyü çok sayfaya yazdırmak için dilimler oluşturabilir. Orijinal görüntü bozulmadan kalır; bölücü yalnızca parçalarını teslim eder.</p>\n<p><a href=\"/tr/gorsel-bol\">Görüntü Bölücü</a> fotoğrafları N'e M ızgara döşemelerine, yatay satırlara ya da dikey şeritlere böler ve parçaları tek tek ya da topluca ZIP olarak indirir. Tamamen tarayıcında çalışır; bu yüzden fotoğrafların cihazından asla çıkmaz.</p>\n<p>Bu kılavuz üç bölme modunu, hazır ayarları, dışa aktarma seçeneklerini ve her modun en iyi gittiği işleri açıklar. Bir Instagram ızgarası planlıyor, bir panoramayı kesiyor ya da uzun bir ekran görüntüsünü yazdırmak için bölüyor ol; bölme aynı basit fikirdir.</p>\n<h2 id=\"what-is-an-image-splitter\">Görüntü bölücü nedir?</h2>\n<p>Görüntü bölücü tek bir görüntüyü düz kesim çizgileri boyunca bir dizi küçük görüntüye böler. 3'e 3 bir ızgara kare bir fotoğrafı dokuz kare döşemeye dönüştürür.</p>\n<p>Yatay şerit bölme yüksek bir görüntüyü üst üste satırlara dönüştürür ve dikey şerit bölme geniş bir görüntüyü yan yana sütunlara dönüştürür.</p>\n<p>Her döşeme gerçek bir görüntü dosyasıdır, kırpma önizlemesi değildir. Döşemeleri tek tek ya da topluca ZIP olarak indirebilir ve ardından ayrı görüntülerin gerekli olduğu her yerde kullanabilirsin: sosyal gönderiler, basılı sayfalar, oyun döşemeleri ya da tasarım maketleri.</p>\n<p>Bölme yıkıcı değildir. Orijinal dosya asla değişmez ve aynı görüntüyü farklı ayarlarla istediğin kadar yeniden bölebilirsin. Bugün 3'e 3 bir ızgara ve yarın 2'ye 4 bir ızgara aynı bozulmamış görüntüden çıkar.</p>\n<p>Bölmek kırpmaktan farklıdır. Kırpma görüntünün bir parçasını tutar ve geri kalanını atar, bölme ise her parçayı korur ve hepsini teslim eder. Döşemeler birlikte orijinal görüntünün tamamını içerir; yalnızca ayrı dosyalardadır.</p>\n<h2 id=\"grid-mode\">Izgara modu: N'e M döşemeler</h2>\n<p>Izgara modu ana moddur. Bir satır ve sütun sayısı belirlersin ve araç görüntüyü o kadar eşit döşemeye böler. 3'e 3 bir ızgara dokuz döşeme, 2'ye 4 bir ızgara sekiz döşeme verir ve en büyük ızgara 10'a 10'dur; bu bir görüntüden yüz döşeme verir.</p>\n<p>Izgara, dokuz kare döşemenin profil sayfasında büyük bir görüntü oluşturduğu Instagram profil ızgaraları için moddur. Ayrıca yapbozlar, mozaikler ve parçaların orijinali yeniden oluşturmak için yan yana oturduğu her tasarım için moddur.</p>\n<p>Her döşeme tam orijinal piksel boyutlarıyla kesilir; bu yüzden 3000 piksel bir fotoğraf 3'e 3 bölündüğünde dokuz adet 1000 piksel döşeme verir. Hiçbir şey küçültülmez ya da yeniden örneklenmez; bu da döşemelerin yazdırma ya da en yüksek kalitede yayımlama için yeterince keskin kalması demektir.</p>\n<p>Önizlemede numaralı kesim çizgileri görünür; bu yüzden indirmeden önce her döşemenin tam olarak nerede başlayıp bittiğini görebilirsin. Bir kesim çizgisi bir yüzden ya da önemli bir ayrıntıdan geçerse kötü bir kesimi kabul etmek yerine ızgarayı değiştir ya da görüntüyü yeniden konumlandır.</p>\n<h2 id=\"horizontal-strips\">Yatay şeritler</h2>\n<p>Yatay şeritler görüntüyü üst üste satırlara keser. Dört yatay şeride bölünmüş yüksek bir görüntü yukarıdan aşağıya okunan dört geniş ve kısa görüntü verir; uzun bir belgenin sayfaları gibi.</p>\n<p>Bu mod yazdırılması gereken uzun ekran görüntüleriyle iyi gider. Tam sayfa bir ekran görüntüsü bir kâğıt yaprağı için çok uzundur ama dört yatay şerit dört sayfaya sorunsuz yazdırılır. Aynı fikir ayrı slaytlar olarak paylaşılması gereken yüksek infografiklerle de işe yarar.</p>\n<p>Yatay şeritler ayrıca her slaydın görüntüyü aşağı doğru sürdürdüğü sosyal kaydırıcılarla iyi gider. Kişi şeritlerde kaydırır ve görüntü sırayla açılır; bu basit bir anlatım etkisi oluşturur.</p>\n<p>Şerit sayısını hedefe göre seç. Dört basılı sayfa için dört şerit, üç slaytlık kaydırıcı için üç şerit ve basit bir yukarı-aşağı bölme için iki şerit. Şeritler aynı yüksekliğe sahiptir; bu yüzden içerik eşit biçimde bölünür.</p>\n<h2 id=\"vertical-strips\">Dikey şeritler</h2>\n<p>Dikey şeritler görüntüyü yan yana sütunlara keser. Üç dikey şeride bölünmüş geniş bir panorama soldan sağa okunan üç yüksek görüntü verir; bir triptik panelleri gibi.</p>\n<p>Bu mod geniş panoramalar ve bir gönderi ya da sayfa için çok geniş banner'larla iyi gider. Dikey şeritlere bölünmüş bir panorama, her kaydırmanın sahnenin sonraki bölümünü açtığı bir kaydırıcı olarak yayımlanabilir; bu seyahat ve manzara fotoğrafçılığıyla iyi gider.</p>\n<p>Dikey şeritler ayrıca sütunlarda yeniden kurulması gereken web sitesi banner'ları ve başlıklarıyla iyi gider. Bir tasarımcı her şeridi kendi sütununa yerleştirebilir ve panoramayı tek bir geniş görüntünün sığmadığı bir düzende yeniden birleştirebilir.</p>\n<p>Yatay şeritlerde olduğu gibi şeritler aynı genişliğe sahiptir; bu yüzden içerik eşit biçimde bölünür. Konusu merkezde olan bir panorama, konunun kesim çizgisinin üzerinde değil, orta şeritte kalması için tek sayıda şeride ihtiyaç duyabilir.</p>\n<h2 id=\"split-presets\">Bölme hazır ayarları</h2>\n<p>Hazır ayarlar yaygın işler için tek tıklamalı bölme ayarlarıdır. 3'e 3 Instagram ızgarası en bilinen hazır ayardır ama araç yaygın ızgara boyutları ve şerit sayıları için başka hazır ayarlar da içerir; bu yüzden satır ve sütunları elle ayarlamayı atlayabilirsin.</p>\n<p>Hazır ayar bir başlangıç noktasıdır, kural değildir. Bir Instagram ızgarası için 3'e 3 hazır ayarına dokun ve ardından görüntün ya da planın başka bir biçim gerektiriyorsa satırları ya da sütunları ayarla. Hazır ayar sayıları doldurur ve sen onları değiştirmekte özgür kalırsın.</p>\n<p>Hazır ayarlar görüntüleri sık böldüğünde yardımcı olur. Her hafta bir ızgara kuran bir sosyal medya yöneticisi her seferinde aynı hazır ayara dokunabilir ve aynı döşeme boyutlarını alabilir; bu profil ızgarasını bir yapbozdan diğerine tutarlı tutar.</p>\n<p>Hiçbir hazır ayar işine uymuyorsa satır ve sütunları elle belirle. Poster için 4'e 5 bir ızgara, banner için 1'e 6 bir şerit ya da mozaik için 5'e 5 bir ızgara hepsi geçerli bölmelerdir ve elle kontroller 10'a 10'a kadar her kombinasyonu kapsar.</p>\n<h2 id=\"full-resolution-tiles\">Tam çözünürlüklü döşemeler</h2>\n<p>Döşemeler tam orijinal piksel boyutlarıyla kesilir; bu da bölmenin asla kalite düşürmediği anlamına gelir. 3000'e 3000 piksel bir fotoğraf dokuz döşemeye bölündüğünde dokuz adet 1000'e 1000 piksel görüntü verir; her biri orijinalin ilgili bölüm kadar keskindir.</p>\n<p>Bu yazdırma ve büyük ekranlar için önemlidir. Küçültülmüş bir döşeme yazdırıldığında ya da tam boyutta görüntülendiğinde yumuşak görünürken tam çözünürlüklü bir döşeme kaynak görüntüyle aynı ayrıntıyı korur. Bölücü bir boyut değiştirici değil, bir kesim aracıdır.</p>\n<p>Karşılığı dosya boyutudur. Tam çözünürlüklü dokuz döşeme birlikte orijinal görüntü kadar ağırdır ve 10'a 10 bir bölme yönetilecek yüz dosya verir. Her döşemeyi elle kaydetmek yerine birlikte tutmak için ZIP indir.</p>\n<p>Sahip olduğun en yüksek çözünürlüklü kaynak görüntüyü kullan. 600 piksel bir fotoğraf 3'e 3 bölündüğünde dokuz adet 200 piksel döşeme verir; bunlar küçük resim olarak iyi görünür ama gönderi olarak kötü görünür. Büyük bir görüntü büyük döşemeler verir ve büyük döşemeler her kullanımda hayatta kalır.</p>\n<h2 id=\"numbered-tiles-and-zip-download\">Numaralı döşemeler ve ZIP indirme</h2>\n<p>Her döşeme nereye gittiğini bilmen için numaralıdır. Numaralandırma okuma düzenini izler: soldan sağa, yukarıdan aşağıya, sol üst köşeden başlar. Döşeme bir sol üst parçadır ve son döşeme sağ alt parçadır.</p>\n<p>Numaralandırma özellikle Instagram ızgaraları için önemlidir; çünkü döşemeler doğru yerlerde kalması için ters sırada yayımlanmalıdır. Sayılar her döşemenin ızgaradaki konumunu gösterir; bu yüzden yayımlama sırası asla tahmin olmaz.</p>\n<p>ZIP indirmesi tüm döşemeleri sırayla adlandırılmış tek bir dosyada içerir. ZIP indirmek her döşemeyi ayrı kaydetmekten daha hızlıdır ve seti cihazında bir arada tutar. Açtığında numaralı dosyalar kullanılmaya hazırdır.</p>\n<p>Yalnızca bir ya da iki tanesine ihtiyacın varsa döşemeleri ayrı da indirebilirsin. Profil fotoğrafı için tek bir döşeme ya da banner için tek bir şerit tüm sete ihtiyaç duymaz ve ayrı indirme açma adımını atlar.</p>\n<h2 id=\"input-formats\">Girdi biçimleri</h2>\n<p>Bölücü 20 MB'ye kadar JPG, PNG, WebP, HEIC, GIF, BMP ve SVG dosyalarını kabul eder. Telefon fotoğrafları, ekran görüntüleri ve tasarım aracı grafikleri dönüştürme olmadan çalışır. iPhone'dan bir HEIC fotoğrafı yüklenir ve diğer dosyalar gibi bölünür.</p>\n<p>Döşemelerin biçimi girdinin değil, senin seçimini izler. Bir JPG görüntü PNG döşemeler üretebilir ve bir PNG JPG döşemeler üretebilir. Biçimi hedefe göre seç: fotoğraflar ve küçük dosyalar için JPG, şeffaflık ve keskin grafikler için PNG.</p>\n<p>Döşeme kalite kontrolünün yalnızca JPG döşemeler için göründüğünü unutma. PNG döşemeler kayıpsızdır; bu yüzden değiştirilecek kalite ayarı yoktur. En küçük dosyalar gerekiyorsa JPG seç ve kaliteyi ayarla; tam pikseller gerekiyorsa PNG seç.</p>\n<p>Hareketli GIF'ler animasyon olarak bölünmez. Hareketli bir GIF yüklemek tek bir karenin döşemelerini verir, hareketli döşemeler seti değil. Izgaralar ve şeritler için sabit bir görüntü böl ve animasyonları bütün tut.</p>\n<h2 id=\"transparency-and-sprite-sheets\">Şeffaflık ve sprite sayfaları</h2>\n<p>Şeffaf bir PNG bölmek her döşemede şeffaflığı korur. Şeffaf hücrelere sahip bir sprite sayfası şeffaf döşemelere bölünür; bu oyun geliştiricilerinin bir simge sayfasını ya da döşeme setini tek tek sprite'lara keserken tam olarak ihtiyaç duyduğu şeydir.</p>\n<p>Şeffaf işler için döşeme biçimi olarak PNG seç. JPG'nin şeffaflığı yoktur; bu yüzden JPG olarak dışa aktarılan şeffaf bir döşeme genellikle beyaz ya da siyah katı bir arka plan kazanır. Şeffaflık yalnızca biçimin desteklediği durumda hayatta kalır.</p>\n<p>Sprite sayfaları tam kesimler ister. 32'ye 32 piksel simgelerden oluşan bir sayfa ızgara olarak bölündüğünde, sayfanın boyutları eşit bölündüğü sürece her biri tam 32 piksel olan döşemeler verir. Oyun motorunda kullanmadan önce bölmeden sonra döşeme boyutlarını incele.</p>\n<p>Sayfa eşit bölünmediğinde kenar döşemeleri boyutta biraz farklı olabilir. Bu ızgara bölmede normaldir ve sayfanın ızgaranın hesaba katmadığı bir kenar boşluğu ya da boşluğu olduğu anlamına gelir.</p>\n<p>Piksel tam döşemeler için kaynak görüntüyü önce tam bir katına kırp.</p>\n<h2 id=\"splitting-for-print\">Yazdırmak için bölme</h2>\n<p>Birçok sayfaya yazdırılmış büyük bir görüntü, bir bölücünün klasik yazdırma kullanımıdır. Bir döşeme ızgarasına bölünmüş bir poster çok sayıda kâğıt yaprağına yazdırılır; bunları keser ve büyük bir posterde birleştirirsin. Döşeme numaraları sırayı gösterir.</p>\n<p>Yatay şeritler birçok sayfaya yazdırılması gereken uzun belgeler ve banner'larla iyi gider. Dört şeride bölünmüş yüksek bir infografik dört sayfaya yazdırılır; her biri orijinalin temiz bir bölümü olur. Şeritler aynı yüksekliğe sahiptir; bu yüzden sayfalar eşleşir.</p>\n<p>Yazdırmadan önce döşeme boyutlarını kâğıt boyutuyla karşılaştır. Yazdırılabilir alanından daha geniş bir döşemeyi yazıcı kırpar, çok daha küçük bir döşeme ise kâğıt boşa harcar. Her döşemenin bir yaprağa uyuması için ızgarayı belirle.</p>\n<p>Tam çözünürlükte yazdır ve yazıcının döşemeleri ölçeklemesine izin verme. Ölçeklenmiş bir döşeme, tam çözünürlüklü bölmenin koruduğu keskinliği kaybeder. Yazıcıyı gerçek boyuta ayarla; döşemeler sorunsuz birleşir.</p>\n<h2 id=\"splitting-screenshots\">Ekran görüntülerini bölme</h2>\n<p>Uzun ekran görüntüleri insanların böldüğü en yaygın şeydir. Bir web sitesinin ya da sohbetin tam sayfa ekran görüntüsü rahat okumak ve yazdırmak için çok uzundur ama yatay şeritler onu okunaklı bölümlere dönüştürür.</p>\n<p>Bir ekran görüntüsünü Ctrl ve V ile doğrudan panodan yapıştır. Bölücü yapıştırılan görüntüleri kabul eder; bu yüzden ekran görüntüsünün asla önce dosya olarak kaydedilmesi gerekmez. Yapıştır, şerit sayısını seç ve bölümleri indir.</p>\n<p>Şerit sayısını içeriğe göre seç. Dört doğal bölümü olan bir ekran görüntüsü dört şeride bölünürken çok uzun bir sayfanın altı ya da sekiz şeride ihtiyacı olabilir. Daha fazla şerit daha kısa ve okunaklı bölümler demektir ama yönetilecek daha fazla dosya da demektir.</p>\n<p>Metinden geçen kesim çizgilerine dikkat et. Bir metin satırını geçen şerit sınırı her iki şeridi de okumayı zorlaştırır. Sınırlar paragraflar ya da bölümler arasındaki boşluklara düşene kadar şerit sayısını ayarla.</p>\n<h2 id=\"common-mistakes\">Yaygın hatalar</h2>\n<p>En yaygın hata düşük çözünürlüklü bir görüntüyü çok fazla döşemeye bölmektir. 600 piksel bir fotoğraf 3'e 3 bölündüğünde dokuz adet 200 piksel döşeme verir; bunlar gönderi olarak kötü görünür. Büyük bir görüntüyle başla ya da daha az döşeme kullan.</p>\n<p>Bir başka hata bir yüzden ya da önemli bir ayrıntıdan geçen kesim çizgisidir. Önizleme indirmeden önce kesim çizgilerini gösterir; bu yüzden onları incele ve ızgarayı ya da görüntünün konumunu ayarla. İki döşemeye bölünmüş bir yüz hata gibi görünür, tasarım gibi değil.</p>\n<p>Üçüncü bir hata yanlış döşeme biçimini seçmektir. JPG olarak dışa aktarılan şeffaf döşemeler şeffaflığını kaybeder ve katı bir arka plan kazanır. Şeffaflık önemli olduğunda her zaman PNG seç ve dosya boyutu önemli olduğunda JPG seç.</p>\n<p>Son olarak birçok kişi ızgaralar için yayımlama sırasını unutur. Instagram önce en yeni gönderiyi gösterir; bu yüzden ızgara döşemeleri düzgün oturması için ters sırada yayımlanmalıdır. Döşeme numaraları ızgaradaki konumu verir; son döşemeden ilke doğru yayımla.</p>\n<h2 id=\"quick-reference\">Hızlı başvuru: bölme kontrol listesi</h2>\n<p>Büyük bir kaynak görüntüyle başla, Izgara, Yatay ya da Dikey modunu seç ve satır ve sütunları belirle ya da hazır ayara dokun. Önizlemedeki numaralı kesim çizgilerini, özellikle yüzler ve metin çevresinde incele.</p>\n<p>Fotoğraflar için JPG ve şeffaflık için PNG seç, ZIP indir ve ızgara döşemelerini ters sırada yayımla. Bir kesim kötü çıkarsa kabul etmek yerine ızgarayı değiştir ve yeniden böl.</p>\n<p>Adım adım sürüm için <a href=\"/tr/blog/gorsel-nasil-bolunur\">Görüntü Nasıl Bölünür?</a> yazısını oku ve Instagram ızgarası ayrıntısı için <a href=\"/tr/blog/gorsel-bol-instagram-izgara\">Instagram Izgara ve Yapbozları için Görüntü Bölme</a> yazısını oku. Görüntünü <a href=\"/tr/gorsel-bol\">Görüntü Bölücü</a> ile böl.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"Görüntü bölmek ile kırpmak arasındaki fark nedir?","answer":"Kırpma bir görüntünün bir parçasını korur ve geri kalanını atar. Bölme her parçayı korur ve hepsini ayrı dosyalar olarak teslim eder. Döşemeler birlikte orijinal görüntünün tamamını içerir; yalnızca düz kesim çizgileri boyunca bölünmüştür."},{"question":"Bölmek fotoğrafımın kalitesini düşürür mü?","answer":"Hayır. Döşemeler tam orijinal piksel boyutlarıyla kesilir; bu yüzden her döşeme kaynak görüntünün ilgili bölümü kadar keskindir. Kalite yalnızca düşük çözünürlüklü bir görüntüyle başlarsan düşer, çünkü döşemeler de küçük kalır."},{"question":"Görüntüyü bölebileceğim en büyük ızgara nedir?","answer":"En büyük ızgara 10'a 10'dur; bu bir görüntüden 100 döşeme verir. Çoğu iş çok daha azına ihtiyaç duyar: Instagram ızgarası için 3'e 3, basit bir bölme için 2'ye 2 ya da uzun bir ekran görüntüsü için bir avuç şerit."},{"question":"Görüntüyü eşit olmayan parçalara bölebilir miyim?","answer":"Hayır, bölücü görüntüyü eşit döşemelere ya da şeritlere böler. Görüntünün boyutları eşit bölünmezse kenar döşemeleri bir ya da iki piksel farklı olabilir. Tam eşit olmayan parçalar için her bölümü ayrı kırpıcı ile kırp."},{"question":"Bölünmüş döşemeler orijinal dosya biçimini korur mu?","answer":"Döşemelerin biçimini sen seçersin. Bir JPG görüntü PNG döşemeler üretebilir ve bir PNG JPG döşemeler üretebilir. Fotoğraflar ve küçük dosyalar için JPG, şeffaflık ya da tam piksel gerektiğinde PNG seç."},{"question":"Fotoğrafın tamamını yayımlamak yerine görüntüyü neden böleyim?","answer":"Bölme tek bir görüntünün yapamadığı işlere yarar: profil sayfasında yapboz ızgarası, kaydırdıkça panoramayı açan bir kaydırıcı, çok sayfaya basılmış bir poster ya da okunaklı bölümlere ayrılmış uzun bir ekran görüntüsü."}];
